#!/usr/bin/env bash
# Commit the removal of every upstream workflow.
#
#   prune_upstream_workflows.sh [--keep FILE] [--output FILE]
#
# Runs on the checked-out branch right after rebase_onto_tag.sh. This fork
# builds on a Linux build host (cluster_build.sh) and runs no GitHub workflow:
# every file under .github/workflows/ came from upstream. Deleting them in one
# generated commit keeps upstream's release, nightly and CI workflows from
# registering (or running) in the fork once the branch is pushed. --keep FILE
# (a name under .github/workflows/) spares one, for a fork that adds its own.
#
# The commit is reproducible: fixed bot identity, author and committer dates
# taken from its parent, so the same rebased tree always yields the same sha
# (an unchanged week then has nothing to push, and no new prerelease is made
# for a commit that already has one). It carries the trailer
#
#   Linux-Sbx-Generated: prune-upstream-workflows
#
# which rebase_onto_tag.sh uses to drop it before the next replay; it is then
# generated again on top of the new tag.
#
# Outputs (--output, default $GITHUB_OUTPUT): sha=<HEAD> pruned=<count>.
# Exit 1 if --keep names a workflow that is not in HEAD.
set -euo pipefail

KEEP=""
OUTPUT="${GITHUB_OUTPUT:-}"
DIR=".github/workflows"
TRAILER="Linux-Sbx-Generated: prune-upstream-workflows"

while [[ $# -gt 0 ]]; do
    case "$1" in
        --keep) KEEP="$2"; shift 2 ;;
        --output) OUTPUT="$2"; shift 2 ;;
        -h|--help) sed -n '2,25p' "$0"; exit 0 ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
done

git rev-parse --git-dir >/dev/null 2>&1 || { echo "error: not inside a git checkout" >&2; exit 1; }
if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
    echo "error: the checkout has uncommitted changes; refusing to commit on top of them" >&2
    exit 1
fi
if [[ -n $KEEP ]]; then
    [[ $KEEP != */* ]] || { echo "error: --keep takes a file name under $DIR, got '$KEEP'" >&2; exit 2; }
    git cat-file -e "HEAD:$DIR/$KEEP" 2>/dev/null \
        || { echo "error: $DIR/$KEEP is not in HEAD" >&2; exit 1; }
    SUBJECT="ci(linux-sbx): keep only ${KEEP} in this fork"
    KEPT="kept $DIR/$KEEP"
else
    SUBJECT="ci(linux-sbx): remove upstream workflows in this fork"
    KEPT="kept none"
fi

DOOMED=()
while IFS= read -r -d '' path; do
    [[ -n $KEEP && $path == "$DIR/$KEEP" ]] || DOOMED+=("$path")
done < <(git ls-files -z -- "$DIR")

if [[ ${#DOOMED[@]} -gt 0 ]]; then
    git rm --quiet -- "${DOOMED[@]}"
    DATE="$(git log -1 --format=%cI HEAD)"
    GIT_AUTHOR_NAME="github-actions[bot]" \
    GIT_AUTHOR_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    GIT_COMMITTER_NAME="github-actions[bot]" \
    GIT_COMMITTER_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    GIT_AUTHOR_DATE="$DATE" GIT_COMMITTER_DATE="$DATE" \
        git -c commit.gpgsign=false commit --quiet --no-verify \
            -m "$SUBJECT" \
            -m "Removes ${#DOOMED[@]} upstream workflow file(s). Generated by prune_upstream_workflows.sh after each rebase; dropped and regenerated on the next one." \
            -m "$TRAILER"
    echo "pruned ${#DOOMED[@]} upstream workflow file(s); $KEPT" >&2
else
    echo "nothing to prune ($KEPT)" >&2
fi

SHA="$(git rev-parse HEAD)"
if [[ -n $OUTPUT ]]; then
    printf 'sha=%s\npruned=%s\n' "$SHA" "${#DOOMED[@]}" >>"$OUTPUT"
fi
echo "$SHA"
